import { useState, useCallback } from "react";
import "./onboarding.css";
import type {
  OnboardingNewAnswersType,
  OnboardingNewPropsType,
  StageIdType,
} from "./types";
import { FLOW_STAGES, INITIAL_LOADING_TEXTS, getStageProcessingTexts } from "./constants";
import { ProcessingStage } from "./partials/ProcessingStage";
import { ChoiceQuestions } from "./partials/ChoiceQuestions";
import { BrandColor } from "./partials/BrandColor";
import { StylePreset } from "./partials/StylePreset";
import { ToggleGrid } from "./partials/ToggleGrid";
import { CompleteStage } from "./partials/CompleteStage";
import {
  BlockStack,
  Box,
  Button,
  InlineStack,
  ProgressBar,
  Text,
  Transition,
} from "@xco-agency/corex-ui";

type ViewStateType = "initial_loading" | "question" | "save_processing" | "complete";

function getStageValidity(
  stageId: StageIdType,
  answers: OnboardingNewAnswersType,
): boolean {
  if (stageId === "volume") {
    return !!answers.volume;
  }
  return true;
}

export function OnboardingNew({
  onGoToDashboard,
  onRestart,
  initialAnswers = {},
  initialCompletedStages = [],
  onSaveStage,
}: OnboardingNewPropsType) {
  const initialCompletedSet = new Set<StageIdType>(initialCompletedStages);
  const allInitiallyComplete =
    FLOW_STAGES.length > 0 && FLOW_STAGES.every((s) => initialCompletedSet.has(s.id));

  // Determine starting index: first incomplete stage
  const firstIncompleteIdx = FLOW_STAGES.findIndex((s) => !initialCompletedSet.has(s.id));
  const startingStageIdx = firstIncompleteIdx >= 0 ? firstIncompleteIdx : 0;

  const [viewState, setViewState] = useState<ViewStateType>(
    allInitiallyComplete ? "complete" : "initial_loading",
  );
  const [stageIndex, setStageIndex] = useState<number>(startingStageIdx);
  const [answers, setAnswers] = useState<OnboardingNewAnswersType>(initialAnswers);
  const [completedStages, setCompletedStages] =
    useState<Set<StageIdType>>(initialCompletedSet);
  const [processingTexts, setProcessingTexts] = useState<string[]>(INITIAL_LOADING_TEXTS);
  const [leaving, setLeaving] = useState(false);

  const currentStage = FLOW_STAGES[stageIndex] || FLOW_STAGES[0]!;
  const canGoBack = stageIndex > 0;
  const isValid = getStageValidity(currentStage.id, answers);

  const handleInitialLoadingDone = useCallback(() => {
    setLeaving(true);
    setTimeout(() => {
      setViewState("question");
      setLeaving(false);
    }, 250);
  }, []);

  const handleContinue = async () => {
    if (!currentStage) return;

    // Call onSaveStage if provided
    const currentAnswer = answers[currentStage.id];
    if (onSaveStage) {
      await onSaveStage(currentStage.id, currentAnswer);
    }

    // Mark current stage as completed
    const nextCompleted = new Set(completedStages);
    nextCompleted.add(currentStage.id);
    setCompletedStages(nextCompleted);

    // Compute contextual dynamic loading texts based on selection
    const texts = getStageProcessingTexts(currentStage.id, answers);
    setProcessingTexts(texts);

    // Transition to save processing
    setLeaving(true);
    setTimeout(() => {
      setViewState("save_processing");
      setLeaving(false);
    }, 250);
  };

  const handleSaveProcessingDone = useCallback(() => {
    // Find next incomplete stage after current stageIndex
    const nextIdx = FLOW_STAGES.findIndex(
      (s, idx) => idx > stageIndex && !completedStages.has(s.id),
    );

    setLeaving(true);
    setTimeout(() => {
      if (nextIdx !== -1) {
        setStageIndex(nextIdx);
        setViewState("question");
      } else {
        // If no subsequent incomplete stage, check if any earlier stage is still incomplete
        const anyIncompleteIdx = FLOW_STAGES.findIndex(
          (s) => !completedStages.has(s.id) && s.id !== currentStage.id,
        );
        if (anyIncompleteIdx !== -1) {
          setStageIndex(anyIncompleteIdx);
          setViewState("question");
        } else {
          setViewState("complete");
        }
      }
      setLeaving(false);
    }, 250);
  }, [stageIndex, completedStages, currentStage?.id]);

  const handleBack = () => {
    if (stageIndex > 0) {
      setLeaving(true);
      setTimeout(() => {
        setStageIndex((i) => i - 1);
        setViewState("question");
        setLeaving(false);
      }, 250);
    }
  };

  const handleReset = () => {
    setAnswers(initialAnswers);
    setCompletedStages(new Set());
    setStageIndex(0);
    setProcessingTexts(INITIAL_LOADING_TEXTS);
    setViewState("initial_loading");
    if (onRestart) onRestart();
  };

  const totalSteps = FLOW_STAGES.length;
  const shownStep = viewState === "complete" ? totalSteps : stageIndex + 1;
  const progressPct =
    viewState === "complete" ? 100 : (completedStages.size / totalSteps) * 100;
  const showProgress = viewState !== "complete";

  return (
    <BlockStack inlineSize="100%" minBlockSize="760px" alignItems="center" padding="base">
      {showProgress && (
        <InlineStack alignItems="center" gap="base">
          <Box inlineSize="90px">
            <ProgressBar progress={progressPct} size="xs" tone="success" />
          </Box>
          <Text color="subdued" variant="small">
            Step {shownStep} of {totalSteps}
          </Text>
        </InlineStack>
      )}

      <BlockStack
        flex={1}
        gap="base"
        alignItems="center"
        justifyContent="center"
        inlineSize="100%"
        maxInlineSize="1200px"
      >
        <Box inlineSize="100%">
          <Transition
            reverse
            key={`${viewState}-${stageIndex}`}
            animate="fade-up"
            leaving={leaving}
            inlineSize="100%"
            display="flex"
            flexDirection="column"
            alignItems="center"
          >
            {viewState === "initial_loading" && (
              <ProcessingStage
                texts={INITIAL_LOADING_TEXTS}
                onDone={handleInitialLoadingDone}
              />
            )}

            {viewState === "save_processing" && (
              <ProcessingStage
                texts={processingTexts}
                onDone={handleSaveProcessingDone}
              />
            )}

            {viewState === "question" && (
              <BlockStack gap="large" inlineSize="100%" alignItems="center">
                {currentStage.id === "volume" && (
                  <ChoiceQuestions answers={answers} setAnswers={setAnswers} />
                )}
                {currentStage.id === "brand" && (
                  <BrandColor answers={answers} setAnswers={setAnswers} />
                )}
                {currentStage.id === "cartStyle" && (
                  <StylePreset answers={answers} setAnswers={setAnswers} />
                )}
                {currentStage.id === "addons" && (
                  <ToggleGrid answers={answers} setAnswers={setAnswers} />
                )}

                <InlineStack
                  gap="base"
                  inlineSize="100%"
                  maxInlineSize="420px"
                  alignItems="center"
                >
                  {canGoBack && (
                    <Button variant="tertiary" onClick={handleBack} icon="arrow-left">
                      Back
                    </Button>
                  )}
                  <Button
                    variant="primary"
                    inlineSize="fill"
                    disabled={!isValid}
                    onClick={handleContinue}
                  >
                    Continue
                  </Button>
                </InlineStack>

                <Text color="subdued">
                  * All configuration are fully customizable anytime from the Hub.
                </Text>
              </BlockStack>
            )}

            {viewState === "complete" && (
              <CompleteStage onRestart={handleReset} onGoToDashboard={onGoToDashboard} />
            )}
          </Transition>
        </Box>
      </BlockStack>
    </BlockStack>
  );
}

export default OnboardingNew;

/* ==========================================================================
   Corex UI - Cart Drawer Placeholder Styles (Minimal CSS)
   Supports 4 presets: Minimal, Bold, Rounded, Editorial
   ========================================================================== */

.cartDrawer {
  --cart-primary: #008060;
  --cart-secondary: #1a1a1a;
  --cart-accent: #e8b84b;
  --cart-bg: #ffffff;
  --cart-surface: #f6f6f7;
  --cart-border: #e1e3e5;
  --cart-text-subdued: #6d7175;
  --cart-radius: 8px;
  --cart-btn-radius: 8px;
  --cart-font: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif;

  width: 100%;
  max-width: 400px;
  height: 100%;
  max-height: 640px;
  margin: 0 auto;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  background: var(--cart-bg);
  color: var(--cart-secondary);
  border: 1px solid var(--cart-border);
  border-radius: var(--cart-radius);
  font-family: var(--cart-font);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
  overflow: hidden;
  user-select: none;
}

/* --------------------------------
   Presets: Minimal, Bold, Rounded, Editorial
-------------------------------- */

.preset-minimal {
  --cart-border: #e5e7eb;
  --cart-radius: 6px;
  --cart-btn-radius: 6px;
  --cart-surface: #f9fafb;
}

.preset-bold {
  --cart-bg: #111215;
  --cart-secondary: #ffffff;
  --cart-surface: #1c1e24;
  --cart-border: #2e323b;
  --cart-text-subdued: #9ba1a6;
  --cart-radius: 10px;
  --cart-btn-radius: 10px;
}

.preset-bold .drawerTitle {
  text-transform: uppercase;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.preset-bold .drawerCheckoutBtn {
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.preset-rounded {
  --cart-radius: 20px;
  --cart-btn-radius: 999px;
  --cart-surface: #f4f5f7;
  --cart-border: #e3e5e8;
}

.preset-rounded .drawerBanner,
.preset-rounded .drawerShippingTrack,
.preset-rounded .drawerQuantity,
.preset-rounded .drawerUpsellBtn,
.preset-rounded .drawerTrustPill {
  border-radius: 999px;
}

.preset-editorial {
  --cart-bg: #fbf9f6;
  --cart-secondary: #1a1815;
  --cart-surface: #f2eee9;
  --cart-border: #dfdbd3;
  --cart-text-subdued: #7d776e;
  --cart-radius: 0px;
  --cart-btn-radius: 0px;
  --cart-font: "Playfair Display", Georgia, "Times New Roman", serif;
}

.preset-editorial .drawerTitle,
.preset-editorial .drawerEyebrow,
.preset-editorial .drawerItemTitle,
.preset-editorial .drawerSummaryRow strong,
.preset-editorial .drawerCheckoutBtn {
  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
}

.preset-editorial .drawerEyebrow {
  font-style: italic;
}

.preset-editorial .drawerCount,
.preset-editorial .placeholderImg,
.preset-editorial .drawerItemThumb,
.preset-editorial .drawerTrustPill {
  border-radius: 0 !important;
}

/* --------------------------------
   1. Announcement Bar
-------------------------------- */

.drawerBanner {
  padding: 8px 12px;
  background: color-mix(in srgb, var(--cart-primary) 12%, transparent);
  color: var(--cart-primary);
  font-size: 11px;
  font-weight: 600;
  text-align: center;
  flex-shrink: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* --------------------------------
   2. Header
-------------------------------- */

.drawerHeader {
  padding: 14px 18px 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--cart-border);
  flex-shrink: 0;
}

.drawerHeaderLeft {
  display: flex;
  flex-direction: column;
}

.drawerEyebrow {
  font-size: 10px;
  font-weight: 600;
  color: var(--cart-text-subdued);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.drawerTitle {
  margin: 2px 0 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--cart-secondary);
  line-height: 1.2;
}

.drawerHeaderRight {
  display: flex;
  align-items: center;
  gap: 8px;
}

.drawerCount {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--cart-secondary) 10%, transparent);
  color: var(--cart-secondary);
  font-size: 11px;
  font-weight: 700;
}

.drawerCloseBtn {
  background: none;
  border: none;
  color: var(--cart-text-subdued);
  font-size: 14px;
  cursor: pointer;
  padding: 4px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* --------------------------------
   3. Free Shipping Tier Bar
-------------------------------- */

.drawerShippingBar {
  padding: 8px 18px;
  background: var(--cart-surface);
  border-bottom: 1px solid var(--cart-border);
  flex-shrink: 0;
}

.drawerShippingText {
  font-size: 11px;
  color: var(--cart-secondary);
  margin-bottom: 6px;
}

.drawerShippingTrack {
  height: 5px;
  background: color-mix(in srgb, var(--cart-secondary) 12%, transparent);
  border-radius: 4px;
  overflow: hidden;
}

.drawerShippingFill {
  height: 100%;
  background: var(--cart-primary);
  border-radius: inherit;
  transition: width 0.3s ease;
}

/* --------------------------------
   4. Items & Placeholders
-------------------------------- */

.drawerItems {
  flex: 1;
  overflow-y: auto;
  padding: 12px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.drawerItem {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--cart-border);
}

.drawerItem:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.drawerItemThumb {
  width: 54px;
  height: 64px;
  flex-shrink: 0;
  border-radius: calc(var(--cart-radius) * 0.7);
  overflow: hidden;
  border: 1px solid var(--cart-border);
  background: var(--cart-surface);
}

.placeholderThumb {
  width: 50px;
  height: 58px;
  flex-shrink: 0;
  border-radius: calc(var(--cart-radius) * 0.7);
  background: var(--cart-surface);
  border: 1px solid var(--cart-border);
}

.placeholderBar {
  background: currentColor;
  opacity: 0.16;
  border-radius: calc(var(--cart-radius) * 0.5);
  height: 8px;
}

.preset-rounded .placeholderBar,
.preset-rounded .placeholderThumb {
  border-radius: 999px;
}

.preset-editorial .placeholderBar,
.preset-editorial .placeholderThumb {
  border-radius: 0 !important;
}

.drawerItemDetails {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.drawerItemTop {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.drawerItemTitle {
  font-size: 13px;
  font-weight: 600;
  color: var(--cart-secondary);
  line-height: 1.3;
}

.drawerItemVariant {
  font-size: 11px;
  color: var(--cart-text-subdued);
  margin-top: 2px;
}

.drawerItemRemove {
  background: none;
  border: none;
  color: var(--cart-text-subdued);
  font-size: 12px;
  cursor: pointer;
  padding: 0;
  line-height: 1;
}

.drawerItemBottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.drawerQuantity {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--cart-border);
  border-radius: var(--cart-btn-radius);
  height: 24px;
  background: var(--cart-bg);
}

.drawerQuantity button {
  background: none;
  border: none;
  color: var(--cart-secondary);
  font-size: 12px;
  width: 22px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.drawerQuantity button:disabled {
  opacity: 0.35;
  cursor: default;
}

.drawerQuantity span {
  font-size: 11px;
  font-weight: 600;
  min-width: 16px;
  text-align: center;
}

.drawerPrice {
  font-size: 13px;
  font-weight: 700;
  color: var(--cart-secondary);
}

/* --------------------------------
   Upsell Recommendation Card
-------------------------------- */

.drawerUpsell {
  padding: 10px 12px;
  background: var(--cart-surface);
  border: 1px solid var(--cart-border);
  border-radius: var(--cart-radius);
  margin-top: 4px;
}

.drawerUpsellHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--cart-text-subdued);
}

.drawerUpsellBadge {
  background: color-mix(in srgb, var(--cart-primary) 15%, transparent);
  color: var(--cart-primary);
  font-size: 9.5px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
}

.drawerUpsellContent {
  display: flex;
  align-items: center;
  gap: 10px;
}

.drawerUpsellThumb {
  width: 36px;
  height: 42px;
  flex-shrink: 0;
  border-radius: calc(var(--cart-radius) * 0.6);
  overflow: hidden;
  border: 1px solid var(--cart-border);
}

.drawerUpsellInfo {
  flex: 1;
  min-width: 0;
}

.drawerUpsellTitle {
  font-size: 12px;
  font-weight: 600;
  color: var(--cart-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.drawerUpsellPrice {
  font-size: 11px;
  color: var(--cart-text-subdued);
  margin-top: 2px;
}

.drawerUpsellBtn {
  background: var(--cart-secondary);
  color: var(--cart-bg);
  border: none;
  font-size: 11px;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: var(--cart-btn-radius);
  cursor: pointer;
  transition: all 0.2s ease;
}

.drawerUpsellBtnAdded {
  background: var(--cart-primary) !important;
  color: #ffffff !important;
}

.drawerPriceGroup {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.drawerComparePrice {
  font-size: 11px;
  text-decoration: line-through;
  color: var(--cart-text-subdued);
}

.cartEmpty {
  text-align: center;
  padding: 36px 16px;
  color: var(--cart-text-subdued);
}

.cartEmptyTitle {
  font-weight: 600;
  color: var(--cart-secondary);
  font-size: 13px;
  margin: 0 0 4px;
}

.cartEmptySubtitle {
  font-size: 11.5px;
  margin: 0;
}

/* --------------------------------
   5. Footer
-------------------------------- */

.drawerFooter {
  padding: 14px 18px 16px;
  border-top: 1px solid var(--cart-border);
  background: var(--cart-bg);
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex-shrink: 0;
  margin-top: auto;
}

.drawerSummaryRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--cart-secondary);
}

.drawerSummaryRow strong {
  font-size: 15px;
  font-weight: 700;
}

.drawerCheckoutBtn {
  width: 100%;
  height: 42px;
  border: none;
  background: var(--cart-primary);
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  border-radius: var(--cart-btn-radius);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.drawerCheckoutBtn:hover {
  opacity: 0.92;
}

.drawerTrustBadges {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex-wrap: wrap;
}

.drawerTrustPill {
  font-size: 9px;
  font-weight: 600;
  color: var(--cart-text-subdued);
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid var(--cart-border);
  background: var(--cart-surface);
}

/* --------------------------------
   Preview Mode (Card Sizing)
-------------------------------- */

.cardDrawerPreview {
  width: 100%;
  height: 280px;
  max-height: 280px;
  overflow: hidden;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cardDrawerPreview .cartDrawer {
  max-width: 100%;
  height: 100%;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
}

.cardDrawerPreview .drawerItems {
  padding: 8px 12px;
  gap: 8px;
}

.cardDrawerPreview .drawerItem {
  padding-bottom: 8px;
  gap: 8px;
}

.cardDrawerPreview .drawerItemThumb,
.cardDrawerPreview .placeholderThumb {
  width: 44px;
  height: 50px;
}

.cardDrawerPreview .drawerItemTitle {
  font-size: 11.5px;
}

.cardDrawerPreview .drawerHeader {
  padding: 10px 12px 8px;
}

.cardDrawerPreview .drawerTitle {
  font-size: 15px;
}

.cardDrawerPreview .drawerFooter {
  padding: 8px 12px 10px;
}

.cardDrawerPreview .drawerCheckoutBtn {
  height: 34px;
  font-size: 11.5px;
  padding: 0 12px;
}

.cardDrawerPreview .drawerTrustBadges {
  display: none;
}

.cardDrawerPreview .drawerUpsell {
  display: none;
}

/* --------------------------------
   Modal Viewport
-------------------------------- */

.modalDeviceViewport {
  width: 100%;
  max-width: 400px;
  height: 640px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* --------------------------------
   Hover Overlay
-------------------------------- */

.cardPreviewWrapper {
  position: relative;
  width: 100%;
  cursor: pointer;
}

.expandOverlayBadge {
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  z-index: 10;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgb(15 17 21 / 88%);
  color: #ffffff;
  font-size: 11px;
  font-weight: 600;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgb(255 255 255 / 25%);
  box-shadow: 0 4px 16px rgb(0 0 0 / 35%);
  opacity: 0;
  pointer-events: none;
  transition: all 200ms ease;
  user-select: none;
  white-space: nowrap;
}

.cardPreviewWrapper:hover .expandOverlayBadge {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

import type {
  BrandColorsType,
  FlowStageConfigType,
  OnboardingNewAnswersType,
  StageIdType,
} from "./types";

export const DEFAULT_BRAND_COLORS: BrandColorsType = {
  primary: "#008060",
  secondary: "#1A1A1A",
  accent: "#E8B84B",
  background: "#F6F6F7",
  source: "default",
};

export const INITIAL_LOADING_TEXTS: string[] = [
  "Initializing your workspace...",
  "Connecting your store...",
  "Getting things ready...",
];

export const FLOW_STAGES: FlowStageConfigType[] = [
  { id: "volume", type: "questions", required: true },
  { id: "brand", type: "questions", required: false },
  { id: "cartStyle", type: "questions", required: false },
  { id: "addons", type: "questions", required: false },
];

export function getStageProcessingTexts(
  stageId: StageIdType,
  answers: OnboardingNewAnswersType,
): string[] {
  switch (stageId) {
    case "volume": {
      const vol = answers.volume;
      const volLabel =
        vol === "under-100"
          ? "under 100 orders"
          : vol === "100-500"
            ? "100–500 orders"
            : vol === "500-2000"
              ? "500–2,000 orders"
              : vol === "2000-plus"
                ? "2,000+ orders"
                : "order volume";
      return [
        `Saving ${volLabel} volume configuration...`,
        "Tuning performance parameters for your store scale...",
      ];
    }
    case "brand": {
      const brand = answers.brand || DEFAULT_BRAND_COLORS;
      return [
        `Applying brand palette (${brand.primary})...`,
        "Compiling custom theme tokens...",
      ];
    }
    case "cartStyle": {
      const style = answers.cartStyle || "minimal";
      const styleLabel = style.charAt(0).toUpperCase() + style.slice(1);
      return [
        `Configuring ${styleLabel} cart drawer layout...`,
        "Integrating brand styles with drawer elements...",
      ];
    }
    case "addons": {
      const count = answers.addons instanceof Set ? answers.addons.size : 0;
      return [
        `Activating ${count} selected revenue tool${count === 1 ? "" : "s"}...`,
        "Finalizing your storefront setup...",
      ];
    }
    default:
      return ["Saving your preferences...", "Getting things ready..."];
  }
}

